    """Tuned Best Fit (lo=10, hi=30, penalty=78): the tightest bin wins, but leaving a gap
    strictly between 10 and 30 units costs 78. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 78 * ((r > 10) & (r < 30))

