    """Tuned Best Fit (lo=0, hi=10, penalty=7): the tightest bin wins, but leaving a gap
    strictly between 0 and 10 units costs 7. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 7 * ((r > 0) & (r < 10))

